// On-chain interaction for sudoku challenges using Lucid Evolution + Blockfrost.
// Requires Vite (or another bundler) to resolve the @lucid-evolution WASM dependency.

// Lucid is loaded lazily via dynamic import so Rollup places it in a separate
// chunk. That chunk has TLA for CML/UPLC WASM init, and the browser resolves
// it fully before this code runs — avoiding "Class extends value undefined".
import { blake2b } from '@noble/hashes/blake2b';

let _lucid = null;
async function getLucid() {
  if (!_lucid) {
    const m = await import('@lucid-evolution/lucid');
    _lucid = {
      ...m,
      ChallengeDatumSchema: m.Data.Object({
        board_id:      m.Data.Integer(),
        board_encoded: m.Data.Bytes(),
        publisher_pkh: m.Data.Bytes(),
      }),
    };
  }
  return _lucid;
}

// ---------------------------------------------------------------------------
// Script constants  (generated by: aiken blueprint apply -v plonk_challenge.spend)
// ---------------------------------------------------------------------------

export const SCRIPT_HASH    = 'e148dfba00dba24086d33451fd56fcf4db777c47472d27a9ec9cc81c';
export const SCRIPT_ADDRESS = 'addr1w8s53ha6qrd6ysyx6v69rl2kln6dkamugarj6fafajwvs8qjv06u4';
const SCRIPT_CBOR ='';

const NETWORK = 'Mainnet';
const BLOCKFROST_URL = 'https://cardano-mainnet.blockfrost.io/api/v0';


// ---------------------------------------------------------------------------
// BLS12-381 constants (for challenge / Lagrange computation)
// ---------------------------------------------------------------------------

const Fp = 4002409555221667393417789825735904156556882819939007885332058136124031650490837864442687629129015664037894272559787n;
const Fr = 52435875175126190479447740508185965837690552500527637822603658699938581184513n;

// ---------------------------------------------------------------------------
// G1 compression (ZCash / BLST serialisation)
// ---------------------------------------------------------------------------

function compressG1(x_str, y_str) {
  const x = BigInt(x_str), y = BigInt(y_str);
  let val = x | (1n << 383n);
  if (y * 2n > Fp) val |= (1n << 381n);
  return hexToBytes(val.toString(16).padStart(96, '0'));
}

function hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) out[i >> 1] = parseInt(hex.slice(i, i + 2), 16);
  return out;
}

function bytesConcat(...arrays) {
  const total = arrays.reduce((s, a) => s + a.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const a of arrays) { out.set(a, off); off += a.length; }
  return out;
}

function bigintToBeBytes(n) {
  const hex = n.toString(16);
  return hexToBytes(hex.length % 2 ? '0' + hex : hex);
}

function intToBE32(n) {
  return hexToBytes(n.toString(16).padStart(64, '0'));
}

function bytesToBigInt(buf) {
  let n = 0n;
  for (const b of buf) n = (n << 8n) | BigInt(b);
  return n;
}

function modFr(n) { return ((n % Fr) + Fr) % Fr; }

function modPow(base, exp, mod) {
  let result = 1n; base = base % mod;
  while (exp > 0n) {
    if (exp % 2n === 1n) result = result * base % mod;
    exp >>= 1n; base = base * base % mod;
  }
  return result;
}

function modInverse(a, m) { return modPow(((a % m) + m) % m, m - 2n, m); }

function blake2b224(buf) {
  return blake2b(buf, { dkLen: 28 });
}

// ---------------------------------------------------------------------------
// Fiat-Shamir challenges (must match on-chain verifier exactly)
// ---------------------------------------------------------------------------

function computeZeta(pre, proof_c, pubInputs) {
  const pubBytes = bytesConcat(...pubInputs.map(intToBE32));
  const betaInput = bytesConcat(
    pre.q_m, pre.q_l, pre.q_r, pre.q_o, pre.q_c,
    pre.s_sig1, pre.s_sig2, pre.s_sig3,
    pubBytes,
    proof_c.commitment_a, proof_c.commitment_b, proof_c.commitment_c,
  );
  const beta  = bytesToBigInt(blake2b224(betaInput)) % Fr;
  const gamma = bytesToBigInt(blake2b224(intToBE32(beta))) % Fr;
  const alpha = bytesToBigInt(blake2b224(bytesConcat(intToBE32(beta), intToBE32(gamma), proof_c.commitment_z))) % Fr;
  const zeta  = bytesToBigInt(blake2b224(bytesConcat(intToBE32(alpha), proof_c.t_low, proof_c.t_mid, proof_c.t_high))) % Fr;
  return zeta;
}

function computeLagrangeInverses(n_val, zeta, gens) {
  return gens.map(gen_i => modInverse(modFr(BigInt(n_val) * modFr(zeta - gen_i)), Fr));
}

// ---------------------------------------------------------------------------
// Minimal CBOR encoder for Plutus Data
// ---------------------------------------------------------------------------

function cborBytesHeader(len) {
  const n = BigInt(len);
  if (n < 24n) return new Uint8Array([0x40 | len]);
  if (n < 0x100n) return new Uint8Array([0x58, len]);
  return new Uint8Array([0x59, len >> 8, len & 0xff]);
}

function cborBytes(buf) { return bytesConcat(cborBytesHeader(buf.length), buf); }

function cborUInt(n) {
  if (n < 24n) return new Uint8Array([Number(n)]);
  if (n < 0x100n) return new Uint8Array([0x18, Number(n)]);
  if (n < 0x10000n) return new Uint8Array([0x19, Number(n >> 8n), Number(n & 0xffn)]);
  if (n < 0x100000000n) return new Uint8Array([0x1a, Number(n>>24n), Number((n>>16n)&0xffn), Number((n>>8n)&0xffn), Number(n&0xffn)]);
  if (n < 0x10000000000000000n) {
    const b = new Uint8Array(9); b[0] = 0x1b;
    const hi = Number(n >> 32n), lo = Number(n & 0xffffffffn);
    b[1]=(hi>>24)&0xff; b[2]=(hi>>16)&0xff; b[3]=(hi>>8)&0xff; b[4]=hi&0xff;
    b[5]=(lo>>24)&0xff; b[6]=(lo>>16)&0xff; b[7]=(lo>>8)&0xff; b[8]=lo&0xff;
    return b;
  }
  const valueBytes = bigintToBeBytes(n);
  return bytesConcat(new Uint8Array([0xc2]), cborBytesHeader(valueBytes.length), valueBytes);
}

function cborInt(n) {
  if (n >= 0n) return cborUInt(n);
  const m = -(n + 1n);
  if (m < 0x10000000000000000n) {
    const enc = cborUInt(m).slice(); enc[0] |= 0x20; return enc;
  }
  const valueBytes = bigintToBeBytes(m);
  return bytesConcat(new Uint8Array([0xc3]), cborBytesHeader(valueBytes.length), valueBytes);
}

function cborArray(items) {
  const n = items.length;
  let header;
  if (n < 24) header = new Uint8Array([0x80 | n]);
  else if (n < 256) header = new Uint8Array([0x98, n]);
  else header = new Uint8Array([0x99, n >> 8, n & 0xff]);
  return bytesConcat(header, ...items);
}

function cborConstr0(fields) {
  return bytesConcat(new Uint8Array([0xd8, 0x79]), cborArray(fields));
}

// ---------------------------------------------------------------------------
// Proof encoding (matches Aiken Proof type field order)
// ---------------------------------------------------------------------------

function encodeProof(p) {
  return cborConstr0([
    cborBytes(p.commitment_a),
    cborBytes(p.commitment_b),
    cborBytes(p.commitment_c),
    cborBytes(p.commitment_z),
    cborBytes(p.t_low),
    cborBytes(p.t_mid),
    cborBytes(p.t_high),
    cborBytes(p.w_omega),
    cborBytes(p.w_omega_zeta),
    cborInt(p.a_eval),
    cborInt(p.b_eval),
    cborInt(p.c_eval),
    cborInt(p.s_sig1_eval),
    cborInt(p.s_sig2_eval),
    cborInt(p.z_omega_eval),
    cborArray(p.lagrange_inverses.map(li => cborInt(li))),
  ]);
}

function encodeRedeemer(pubInputs, proof) {
  return cborArray([
    cborArray(pubInputs.map(x => cborInt(x))),
    encodeProof(proof),
  ]);
}

// ---------------------------------------------------------------------------
// Board encoding / decoding (matches boardId.js encodeBoard)
// ---------------------------------------------------------------------------

export function encodeBoard(board) {
  const bytes = new Uint8Array(41);
  bytes[0] = board[0][0];
  for (let k = 1; k <= 40; k++) {
    const cell1 = board[Math.floor((2 * k - 1) / 9)][(2 * k - 1) % 9];
    const cell2 = board[Math.floor((2 * k) / 9)][(2 * k) % 9];
    bytes[k] = (cell1 << 4) | cell2;
  }
  return bytes;
}

export function decodeBoard(bytes) {
  const board = Array.from({ length: 9 }, () => new Array(9).fill(0));
  board[0][0] = bytes[0] & 0x0f;
  for (let k = 1; k <= 40; k++) {
    const cell1 = (bytes[k] >> 4) & 0x0f;
    const cell2 = bytes[k] & 0x0f;
    board[Math.floor((2 * k - 1) / 9)][(2 * k - 1) % 9] = cell1;
    board[Math.floor((2 * k) / 9)][(2 * k) % 9] = cell2;
  }
  return board;
}

// ---------------------------------------------------------------------------
// Lucid helpers
// ---------------------------------------------------------------------------

async function makeLucid(blockfrostKey) {
  const { Lucid, Blockfrost } = await getLucid();
  return Lucid(new Blockfrost(BLOCKFROST_URL, blockfrostKey), NETWORK);
}

async function connectEternl(lucid) {
  if (!window.cardano?.eternl) throw new Error('Eternl wallet not found. Please install the Eternl extension.');
  const api = await window.cardano.eternl.enable();
  lucid.selectWallet.fromAPI(api);
  return lucid;
}

// ---------------------------------------------------------------------------
// Deploy challenge
// ---------------------------------------------------------------------------

export async function deployChallenge(blockfrostKey, board, boardId, lovelace) {
  const { Data, toHex, getAddressDetails, ChallengeDatumSchema } = await getLucid();
  const lucid = await connectEternl(await makeLucid(blockfrostKey));

  const walletAddress = await lucid.wallet().address();
  const { paymentCredential } = getAddressDetails(walletAddress);
  if (!paymentCredential) throw new Error('Could not read payment credential from wallet address.');
  const publisherPkh = paymentCredential.hash;

  const boardEncoded = encodeBoard(board);
  const datum = Data.to(
    {
      board_id:      BigInt(boardId),
      board_encoded: toHex(boardEncoded),
      publisher_pkh: publisherPkh,
    },
    ChallengeDatumSchema,
  );

  const tx = await lucid.newTx()
    .pay.ToAddressWithData(
      SCRIPT_ADDRESS,
      { kind: 'inline', value: datum },
      { lovelace: BigInt(lovelace) },
    )
    .complete();

  const signed = await tx.sign.withWallet().complete();
  return signed.submit();
}

// ---------------------------------------------------------------------------
// Fetch challenges (Blockfrost UTxO query)
// ---------------------------------------------------------------------------

export async function fetchChallenges(blockfrostKey) {
  const { Data, fromHex, ChallengeDatumSchema } = await getLucid();
  const resp = await fetch(
    `${BLOCKFROST_URL}/addresses/${SCRIPT_ADDRESS}/utxos`,
    { headers: { project_id: blockfrostKey } },
  );
  if (resp.status === 404) return [];
  if (!resp.ok) throw new Error(`Blockfrost error: ${resp.status} ${resp.statusText}`);
  const utxos = await resp.json();

  const challenges = [];
  for (const utxo of utxos) {
    if (!utxo.inline_datum) continue;
    try {
      const decoded = Data.from(utxo.inline_datum, ChallengeDatumSchema);
      const boardEncoded = fromHex(decoded.board_encoded);
      challenges.push({
        txHash:       utxo.tx_hash,
        outputIndex:  utxo.output_index,
        boardId:      decoded.board_id.toString(),
        boardEncoded,
        board:        decodeBoard(boardEncoded),
        publisherPkh: decoded.publisher_pkh,
        lovelace:     BigInt(utxo.amount.find(a => a.unit === 'lovelace').quantity),
      });
    } catch (_) {
      // Not a valid ChallengeDatum — skip
    }
  }
  return challenges;
}

// ---------------------------------------------------------------------------
// Claim challenge (spend UTxO with PLONK proof)
// ---------------------------------------------------------------------------

let _vkCache = null;
async function loadVK() {
  if (!_vkCache) {
    const r = await fetch(import.meta.env.BASE_URL + 'verification_key.json');
    if (!r.ok) throw new Error('Could not load verification_key.json');
    _vkCache = await r.json();
  }
  return _vkCache;
}

function buildProofCompressed(proofJson, vkJson, pubInputs) {
  function generatorPowers(omega_str, nPublic) {
    const omega = BigInt(omega_str);
    const powers = []; let cur = 1n;
    for (let i = 0; i <= nPublic; i++) { powers.push(modFr(cur)); cur = modFr(cur * omega); }
    return powers;
  }

  const n_val = Math.pow(2, vkJson.power);
  const gens  = generatorPowers(vkJson.w, vkJson.nPublic);

  const pre = {
    q_m:    compressG1(vkJson.Qm[0], vkJson.Qm[1]),
    q_l:    compressG1(vkJson.Ql[0], vkJson.Ql[1]),
    q_r:    compressG1(vkJson.Qr[0], vkJson.Qr[1]),
    q_o:    compressG1(vkJson.Qo[0], vkJson.Qo[1]),
    q_c:    compressG1(vkJson.Qc[0], vkJson.Qc[1]),
    s_sig1: compressG1(vkJson.S1[0], vkJson.S1[1]),
    s_sig2: compressG1(vkJson.S2[0], vkJson.S2[1]),
    s_sig3: compressG1(vkJson.S3[0], vkJson.S3[1]),
  };

  const proof_c = {
    commitment_a:   compressG1(proofJson.A[0],   proofJson.A[1]),
    commitment_b:   compressG1(proofJson.B[0],   proofJson.B[1]),
    commitment_c:   compressG1(proofJson.C[0],   proofJson.C[1]),
    commitment_z:   compressG1(proofJson.Z[0],   proofJson.Z[1]),
    t_low:          compressG1(proofJson.T1[0],  proofJson.T1[1]),
    t_mid:          compressG1(proofJson.T2[0],  proofJson.T2[1]),
    t_high:         compressG1(proofJson.T3[0],  proofJson.T3[1]),
    w_omega:        compressG1(proofJson.Wxi[0], proofJson.Wxi[1]),
    w_omega_zeta:   compressG1(proofJson.Wxiw[0],proofJson.Wxiw[1]),
    a_eval:         BigInt(proofJson.eval_a),
    b_eval:         BigInt(proofJson.eval_b),
    c_eval:         BigInt(proofJson.eval_c),
    s_sig1_eval:    BigInt(proofJson.eval_s1),
    s_sig2_eval:    BigInt(proofJson.eval_s2),
    z_omega_eval:   BigInt(proofJson.eval_zw),
  };

  const zeta = computeZeta(pre, proof_c, pubInputs);
  proof_c.lagrange_inverses = computeLagrangeInverses(n_val, zeta, gens);
  return proof_c;
}

// ---------------------------------------------------------------------------
// Retract challenge (publisher reclaims their UTxO)
// ---------------------------------------------------------------------------

export async function retractChallenge(blockfrostKey, challenge) {
  const { toHex, getAddressDetails } = await getLucid();
  const lucid = await connectEternl(await makeLucid(blockfrostKey));

  const walletAddress = await lucid.wallet().address();
  const { paymentCredential } = getAddressDetails(walletAddress);
  if (!paymentCredential) throw new Error('Could not read payment credential from wallet.');
  if (paymentCredential.hash !== challenge.publisherPkh)
    throw new Error('Connected wallet is not the publisher of this challenge.');

  // The validator returns True on the signed_by_publisher path before using the
  // redeemer, but Aiken deserialises it at entry, so we must pass a structurally
  // valid (List<Int>, Proof) even though every field is a dummy zero value.
  const zero48 = new Uint8Array(48);
  const dummyProof = {
    commitment_a: zero48, commitment_b: zero48, commitment_c: zero48,
    commitment_z: zero48, t_low: zero48, t_mid: zero48, t_high: zero48,
    w_omega: zero48, w_omega_zeta: zero48,
    a_eval: 0n, b_eval: 0n, c_eval: 0n,
    s_sig1_eval: 0n, s_sig2_eval: 0n, z_omega_eval: 0n,
    lagrange_inverses: [],
  };
  const redeemerHex = toHex(encodeRedeemer([], dummyProof));

  const script = { type: 'PlutusV3', script: SCRIPT_CBOR };
  const utxos = await lucid.utxosByOutRef([{ txHash: challenge.txHash, outputIndex: challenge.outputIndex }]);
  if (!utxos.length) throw new Error('UTxO not found (already spent?)');

  const tx = await lucid.newTx()
    .collectFrom(utxos, redeemerHex)
    .attach.SpendingValidator(script)
    .addSigner(walletAddress)
    .complete({ localUPLCEval: false });

  const signed = await tx.sign.withWallet().complete();
  return signed.submit();
}

// ---------------------------------------------------------------------------
// Claim challenge (spend UTxO with PLONK proof)
// ---------------------------------------------------------------------------

export async function claimChallenge(blockfrostKey, challenge, proofJson) {
  const { toHex } = await getLucid();
  const lucid = await connectEternl(await makeLucid(blockfrostKey));

  const vkJson = await loadVK();
  const pubInputs = [BigInt(challenge.boardId)];
  const proof_c = buildProofCompressed(proofJson, vkJson, pubInputs);
  const redeemerBytes = encodeRedeemer(pubInputs, proof_c);
  const redeemerHex = toHex(redeemerBytes);

  const script = { type: 'PlutusV3', script: SCRIPT_CBOR };

  const utxos = await lucid.utxosByOutRef([{
    txHash: challenge.txHash,
    outputIndex: challenge.outputIndex,
  }]);
  if (!utxos.length) throw new Error('UTxO not found (already spent?)');

  const tx = await lucid.newTx()
    .collectFrom(utxos, redeemerHex)
    .attach.SpendingValidator(script)
    .complete({ localUPLCEval: false });

  const signed = await tx.sign.withWallet().complete();
  return signed.submit();
}
